 7	    static int findIndex(int[] sortedValues, int target) {
 8	        int low = 0;
 9	        int high = sortedValues.length - 1;
10	
11	        while (low <= high) {
12	            int middle = low + (high - low) / 2;
13	            int middleValue = sortedValues[middle];
